@startuml

class Student {
  + name : string
  + email : string
}

class Tutor {
  + name : string
  + email : string
  + bankAccount : string
}

class Subject {}

class ExpertiseLevel {}

class TutoringOffer {
  + hourlyPrice : float
}

class Availability {
  + day : string
  + startTime : time
  + endTime : time
}

class TutoringRequest {
  + targetDate : date
  + targetTime : time
  + level : ExpertiseLevel
}

class TutoringSession {
  + date : date
  + time : time
  + isCancelled : boolean
}

class Payment {
  + amount : float
  + method : string
}

Tutor "0..1" -- "0..*" Student : may also be a
Student "1" -- "*" TutoringRequest : makes
Tutor "1" -- "*" TutoringRequest : receives
TutoringRequest "1" -- "0..1" TutoringSession : becomes
Student "1" -- "*" TutoringSession : attends
Tutor "1" -- "*" TutoringSession : conducts
TutoringSession "1" -- "0..1" Payment : results in
Tutor "1" -- "*" TutoringOffer : offers
TutoringOffer "*" -- "1" Subject : in
TutoringOffer "*" -- "1" ExpertiseLevel : at
Tutor "1" -- "*" Availability : specifies
Tutor "1" -- "*" TutoringOffer : provides

@enduml

